#include <iostream>
#include <string_view>

class ResourceGuard {
private:
    std::string_view name;
public:
    explicit ResourceGuard(std::string_view n) : name(n) {
        std::cout << "Acquiring resource: " << name << '\n';
    }

    ~ResourceGuard() {
        std::cout << "Releasing resource: " << name << '\n';
    }
};

int main() {
    std::cout << "Entering outer scope\n";
    {
        ResourceGuard resA{"Resource_A"};
        {
            ResourceGuard resB{"Resource_B"};
            std::cout << "Inside innermost block\n";
        }
        std::cout << "Exited innermost block\n";
    }
    std::cout << "Exited outer block\n";
    return 0;
}

#include <iostream>
#include <string>

class Tracer {
private:
    int id;
    std::string description;
public:
    Tracer(int objectId, std::string desc)
        : id(objectId), description(std::move(desc)) {
        std::cout << "Object " << id << "   constructor runs   " << description << '\n';
    }

    ~Tracer() {
        if (id == 1 || id == 6) {
            std::cout << '\n';
        }
        std::cout << "Object " << id << "   destructor runs    " << description << '\n';
    }
};

// 1. Global object
Tracer globalObj(1, "(global before main)");

void create() {
    std::cout << "\nCREATE FUNCTION: EXECUTION BEGINS\n";
    Tracer fifth(5, "(local automatic in create)");
    static Tracer sixth(6, "(local static in create)");
    Tracer seventh(7, "(local automatic in create)");
    std::cout << "\nCREATE FUNCTION: EXECUTION ENDS\n";
}

int main() {
    std::cout << "\nMAIN FUNCTION: EXECUTION BEGINS\n";
    Tracer second(2, "(local automatic in main)");
    static Tracer third(3, "(local static in main)");

    create();

    std::cout << "\nMAIN FUNCTION: EXECUTION RESUMES\n";
    Tracer fourth(4, "(local automatic in main)");
    std::cout << "\nMAIN FUNCTION: EXECUTION ENDS\n";
    return 0;
}
